        {
          "n": 1,
          "text": "॥ श्रीगणेशाय नमः ॥",
          "end": "space"
        }
      ],
      "uncertain": false,
      "note": null
    },
    {
      "id": "r2",
      "type": "heading",
      "lines": [
        {
          "n": 1,
          "text": "। अथ वैराग्यशतकम् ।",
          "end": "space"
        }
      ],
      "uncertain": false,
      "note": null
    },
    {
      "id": "r3",
      "type": "verse",
      "lines": [
        {
          "n": 1,
          "text": "दिक्कालाद्यनवच्छिन्नानन्तचिन्मात्रमूर्तये ।",
          "end": "line"
        },
        {
          "n": 2,
          "text": "स्वानुभूत्येकमानाय नमः शान्ताय तेजसे ॥ १ ॥",
          "end": "space"
        }
      ],
      "uncertain": false,
      "note": null
    },
    {
      "id": "r4",
      "type": "heading",
      "lines": [
        {
          "n": 1,
          "text": "अथ तृष्णादूषणम् ।",
          "end": "space"
        }
      ],
      "uncertain": false,
      "note": null
    },
    {
      "id": "r5",
      "type": "verse",
      "lines": [
        {
          "n": 1,
          "text": "बोद्धारो मत्सरग्रस्ताः प्रभवः स्मयदूषिताः ।",
          "end": "line"
        },
        {
          "n": 2,
          "text": "अबोधोपहताश्चान्ये जीर्णमङ्गे सुभाषितम् ॥ २ ॥",
          "end": "space"
        }
      ],
      "uncertain": false,
      "note": null
    },
    {
      "id": "r6",
      "type": "verse",
      "lines": [
        {
          "n": 1,
          "text": "न संसारोत्पन्नं चरितमनुपश्यामि कुशलं",
          "end": "line"
        },
        {
          "n": 2,
          "text": "विपाकः पुण्यानां जनयति भयं मे विमृशतः ।",
          "end": "line"
        },
        {
          "n": 3,
          "text": "महद्भिः पुण्यौघैश्चिरपरिगृहीताश्च विषया",
          "end": "line"
        },
        {
          "n": 4,
          "text": "महान्तो जायन्ते व्यसनमिव दातुं विषयिणाम् ॥ ३ ॥",
          "end": "space"
        }
      ],
      "uncertain": false,
      "note": null
    },
    {
      "id": "r7",
      "type": "verse",
      "lines": [
        {
          "n": 1,
          "text": "उत्खातं निधिशङ्कया क्षितितलं ध्माता गिरेर्धातवो",
          "end": "line"
        },
        {
          "n": 2,
          "text": "निस्तीर्णः सरितां पतिर्नृपतयो यत्नेन संतोषिताः ।",
          "end": "line"
        },
        {
          "n": 3,
          "text": "मन्त्राराधनतत्परेण मनसा नीताः श्मशाने निशाः",
          "end": "line"
        },
        {
          "n": 4,
          "text": "प्राप्तः काणवराटकोपि न मया तृष्णेधुना मुञ्च माम् ॥ ४ ॥",
          "end": "space"
        }
      ],
      "uncertain": false,
      "note": null
    },
    {
      "id": "r8",
      "type": "apparatus_entry",
      "lines": [
        {
          "n": 1,
          "text": "I. (a) चिन्मात्र; विज्ञान. M. (b) °त्ये°; °त्यै° B. M. °माना°; नाथा°. P.",
          "end": "space"
        }
      ],
