    {
      "id": "r10",
      "type": "apparatus_entry",
      "lines": [
        {
          "n": 1,
          "text": "III. (c) परिगृहीताश्च; °मपि गृहीताश्च. K. G. Bo. (orig. Bo.n.) परिगृही-",
          "end": "hyphen"
        },
        {
          "n": 2,
          "text": "ता हि. B.",
          "end": "space"
